import { escapeHtml as e, label, roleLabels, needStatuses, money, dateText, timeText, localDate, markdown, isClosed, canRespond } from "./domain.js";
import { icon } from "./icons.js";
import { labelChips } from "./directory-v12.js";
import { field, selectField, checkField, richField, tagField, footerSubmit, button, badge, tags, avatar, empty } from "./ui.js";
const formatOptions = ["distance", "site", "mixte"].map(v => ({ value: v, label: label(v) }));
const fromCents = (v) => v == null ? "" : String(v / 100);
export function needForm(ctx, need, companies = []) {
    return `<form id="command-form" class="ec13-wizard" data-command="save_need" data-id="${need?.id || ""}"><div class="ec13-steps"><button type="button" class="ec13-step active" data-action="wizard-step" data-step="0">1 · Projet</button><button type="button" class="ec13-step" data-action="wizard-step" data-step="1">2 · Conditions</button><button type="button" class="ec13-step" data-action="wizard-step" data-step="2">3 · Diffusion</button></div><div class="inline-note compact"><span>${icon("info", 20)}</span><p>Un seul brief partag\u00E9 avec les prestataires. Votre identit\u00E9 est affich\u00E9e uniquement selon leurs droits Premium ; les contacts restent soumis \u00E0 votre accord.</p></div><div class="form-grid"><div class="ec13-wizard-panel span-2" data-wizard-panel="0"><label class="field">Modèle de brief<select id="ec13-template"><option value="">Partir d’un brief vierge</option><option value="audit">Audit</option><option value="juridique">Juridique</option><option value="recrutement">Recrutement</option><option value="financement">Financement</option></select></label></div><div class="form-section-title span-2"><span>01</span><div><strong>La startup</strong><small>La confidentialit\u00E9 de son identit\u00E9 reste garantie par les droits d\u0027acc\u00E8s.</small></div></div>${ctx.boot.user.role === "admin" ? selectField("company", "Startup concern\u00E9e", companies.filter(c => c.type === "startup").map(c => ({ value: c.id, label: c.name })), need?.company_id || ctx.companyId || "", true) : `<div class="field span-2"><label>Publi\u00E9 au nom de</label><div class="readonly-field">${icon("company", 17)}${e(ctx.company?.name || "Configurez votre entreprise avant de publier.")}</div><input type="hidden" name="company" value="${e(need?.company_id || ctx.companyId || "")}"></div>`}
 <div class="form-section-title span-2"><span>02</span><div><strong>Le projet &amp; les livrables</strong><small>Plus le brief est clair, plus les propositions seront pertinentes.</small></div></div>${field("title", "Titre du besoin", need?.title || "", { required: true, placeholder: "Ex. Structurer notre strat\u00E9gie r\u00E9glementaire", wide: true })}${richField("context", "Contexte et enjeux", need?.context || "")}
 ${field("objectives", "Objectifs \u00E0 atteindre", need?.objectives || "", { type: "textarea", placeholder: "Qu attendez-vous concr\u00E8tement de cette mission ?" })}${field("deliverables", "Livrables attendus", need?.deliverables || "", { type: "textarea", placeholder: "Audit, feuille de route, prototype, dossier..." })}${field("constraints", "Contraintes et informations utiles", need?.constraints || "", { type: "textarea", wide: true, placeholder: "Disponibilit\u00E9 de vos \u00E9quipes, maturit\u00E9 du projet, contraintes techniques..." })}
 <div class="form-section-title span-2"><span>03</span><div><strong>Conditions &amp; diffusion</strong><small>Pr\u00E9cisez le calendrier et les mots-cl\u00E9s qui aideront le matching.</small></div></div>${tagField(need?.tags || [])}${field("budget_min", "Budget minimum (EUR HT)", fromCents(need?.budget_min), { type: "number", min: 0 })}${field("budget_max", "Budget maximum (EUR HT)", fromCents(need?.budget_max), { type: "number", min: 0, help: "Laissez vide si le budget reste \u00E0 d\u00E9finir." })}
 ${field("deadline", "Date limite de r\u00E9ponse", need?.deadline?.slice(0, 10) || "", { type: "date" })}${selectField("format", "Modalit\u00E9 de la mission", formatOptions, need?.format || "distance")}
 <details class="form-section span-2"><summary>${icon("lock", 17)}Contact r\u00E9serv\u00E9 aux prestataires Premium</summary><div class="form-grid">${field("contact_name", "Contact de la mission", need?.contact?.name || "")}${field("contact_email", "Email professionnel", need?.contact?.email || "", { type: "email" })}${field("contact_phone", "T\u00E9l\u00E9phone", need?.contact?.phone || "", { type: "tel" })}<div class="span-2">${checkField("share_contact", "J'autorise les prestataires Premium a consulter ces coordonn\u00E9es.", need?.contact?.shared || false)}</div></div></details>
 ${!need || need.status === "brouillon" ? selectField("status", "Publication", [{ value: "ouvert", label: "Publier dans la bourse des besoins" }, { value: "brouillon", label: "Conserver en brouillon" }], need?.status || "ouvert", true) : "<input type=\"hidden\" name=\"status\" value=\"ouvert\">"}</div><div class="ec13-wizard-controls"><span id="ec13-draft-state">Brouillon conservé dans ce navigateur.</span><button class="btn ghost" type="button" data-action="wizard-prev">Précédent</button><button class="btn primary" type="button" data-action="wizard-next">Continuer</button></div><div class="ec13-preview" id="ec13-preview" hidden><h3>Aperçu visible par le prestataire</h3><p>La startup reste anonyme pour un prestataire non Premium.</p><div id="ec13-preview-text"></div></div><div class="ec13-wizard-submit">${footerSubmit(need ? "Enregistrer les modifications" : "Publier ou enregistrer")}</div></form>`;
}
export function needDetail(ctx, data) {
    const n = data.need;
    const role = ctx.boot.user.role;
    const isProvider = role === "prestataire";
    const stage = n.my_response ? "Proposition transmise" : data.responses.length ? "Propositions à examiner" : "Demande publiée";
    const nextText = n.can_edit ? (data.responses.length ? "Comparez les réponses reçues et choisissez comment poursuivre." : "Votre demande est visible. Vous pouvez préciser le brief ou solliciter votre manager.") : n.my_response ? "Votre réponse est enregistrée. Retrouvez votre échange et préparez la prochaine étape." : "Évaluez le besoin, puis proposez une approche adaptée à la startup.";
    const primaryAction = n.can_edit ? (data.responses.length ? button("Examiner les propositions", "go-responses", { id: n.id, class: "primary", icon: "messages" }) : button("Améliorer ma demande", "edit-need", { id: n.id, class: "primary", icon: "edit" })) : n.my_response ? button("Accéder à mes échanges", "open-thread", { id: n.my_response, class: "primary", icon: "messages" }) : canRespond(role, ctx.company, n) ? button("Répondre à cette opportunité", "respond", { id: n.id, class: "primary", icon: "send" }) : "";
    const lifecycle = n.owned ? `<div class="ec22-lifecycle">${button("Archiver la demande", "need-archive", { id: n.id, class: "small ghost" })}${data.responses.length === 0 && (n.responses_count || 0) === 0 ? button("Supprimer sans réponse", "need-delete", { id: n.id, class: "small ghost" }) : ""}</div>` : "";
    const actionStrip = `<section class="ec21-action-strip" aria-label="Prochaine étape"><div class="ec21-action-copy"><span class="ec21-kicker">${n.can_edit ? "MON DOSSIER" : isProvider ? "MON OPPORTUNITÉ" : "SUIVI"} · ${e(stage)}</span><h3>${n.can_edit ? "Quelle est la prochaine étape ?" : n.my_response ? "Votre proposition est bien envoyée" : "Une expertise à proposer ?"}</h3><p>${e(nextText)}</p></div><div class="ec21-action-buttons">${primaryAction}${n.can_edit ? `<a class="ec21-subtle-link" href="#dashboard">Revenir à mon tableau de bord →</a>` : n.my_response ? `<a class="ec21-subtle-link" href="#messages">Voir mes conversations →</a>` : ""}</div></section>`;
    return actionStrip + lifecycle + `<div class="need-detail-head"><div class="detail-badges">${badge(n.status)}${!n.identity_visible ? "<span class=\"protected-label\">" + icon("lock", 14) + "Identit\u00E9 de la startup prot\u00E9g\u00E9e</span>" : "<span class=\"need-owner\">" + icon("company", 15) + e(n.company_name) + "</span>"}</div><h2 class="detail-title">${e(n.title)}</h2><div class="need-progress" aria-label="Avancement de la mise en relation">${[["Besoin publi\u00E9", true], ["Propositions re\u00E7ues", data.responses.length > 0 || Boolean(n.my_response)], ["D\u00E9cision", data.responses.some(r => ["en_discussion", "retenue"].includes(r.status))], ["Collaboration", ["rdv_planifie", "devis_recu", "en_realisation", "termine"].includes(n.status)]].map(([text, done], i) => `<span class="progress-step ${done ? "complete" : ""}"><i>${done ? icon("check", 13) : i + 1}</i><span>${text}</span></span>`).join("")}</div>${tags(n.tags)}<div class="detail-facts"><div><span>Budget indicatif</span><strong>${n.budget_min !== null ? money(n.budget_min) + " - " : ""}${n.budget_max !== null ? money(n.budget_max) : "\u00C0 d\u00E9finir"}</strong></div><div><span>R\u00E9ponses attendues avant</span><strong>${dateText(n.deadline)}</strong></div><div><span>Modalit\u00E9</span><strong>${e(label(n.format))}</strong></div><div><span>Publi\u00E9 le</span><strong>${dateText(n.created_at)}</strong></div></div></div>
 <div class="detail-layout"><div><section class="brief-section"><h3>${icon("needs", 18)}Comprendre le besoin</h3><div class="prose">${markdown(n.context)}</div></section>${n.objectives ? `<section class="brief-section"><h3>${icon("target", 18)}Objectifs</h3><div class="prose">${markdown(n.objectives)}</div></section>` : ""}${n.deliverables ? `<section class="brief-section"><h3>${icon("check", 18)}Livrables attendus</h3><div class="prose">${markdown(n.deliverables)}</div></section>` : ""}${n.constraints ? `<section class="brief-section"><h3>${icon("info", 18)}Contraintes et contexte utile</h3><div class="prose">${markdown(n.constraints)}</div></section>` : ""}</div>
 <aside><div class="detail-action-box"><h3>${n.can_edit ? "Piloter ma demande" : n.my_response ? "Votre proposition est envoy\u00E9e" : "Votre expertise peut faire la diff\u00E9rence."}</h3><p>${n.can_edit ? "Vous choisissez avec qui poursuivre. Le statut de la demande est visible dans la bourse." : n.my_response ? "Retrouvez votre r\u00E9ponse et continuez l'\u00E9change dans votre dossier." : "Expliquez votre approche, ce que vous livrez et votre calendrier."}</p>${n.can_edit ? ((data.responses.length ? button("Examiner les propositions", "go-responses", { id: n.id, class: "full primary", icon: "messages" }) : button("Modifier mon besoin", "edit-need", { id: n.id, class: "full primary", icon: "edit" })) + button("Mettre \u00E0 jour le statut", "need-status", { id: n.id, class: "full", icon: "needs" }) + (data.responses.length ? button("Modifier le brief", "edit-need", { id: n.id, class: "full ghost", icon: "edit" }) : "")) : n.my_response ? button("Ouvrir mon dossier", "open-thread", { id: n.my_response, class: "full primary", icon: "messages" }) : canRespond(role, ctx.company, n) ? button("Proposer mon expertise", "respond", { id: n.id, class: "full primary", icon: "send" }) : role === "prestataire" ? "<p class=\"muted\">" + (ctx.company?.provider_status !== "valide" ? "Votre entreprise doit \u00EAtre valid\u00E9e pour r\u00E9pondre." : ctx.company?.member_role === "collaborateur" ? "Un gestionnaire de votre entreprise doit envoyer la proposition." : "Cette demande ne recoit plus de nouvelles propositions.") + "</p>" : ""}</div>
 ${role === "prestataire" && !n.identity_visible ? `<div class="premium-detail"><span>${icon("lock", 22)}</span><h4>L'identit\u00E9, pas le contexte.</h4><p>Le brief est lisible et vous pouvez r\u00E9pondre. Premium permet d'identifier la startup et de voir ses contacts autoris\u00E9s.</p>${button("En savoir plus", "premium", { class: "small ghost" })}</div>` : ""}
 ${n.contact ? `<div class="contact-detail"><h4>Contact de la mission</h4><p>${e(n.contact.name || "Non renseign\u00E9")}</p>${n.contact.email ? `<a href="mailto:${e(n.contact.email)}">${e(n.contact.email)}</a>` : ""}<p>${e(n.contact.phone)}</p>${!n.contact.shared && n.owned ? "<small>Partage Premium d\u00E9sactiv\u00E9.</small>" : ""}</div>` : ""}</aside></div>
 ${(n.owned || role === "startup_manager" || role === "admin") ? `<section class="responses-section" id="need-responses"><div class="section-heading"><div><p class="eyebrow">PROPOSITIONS RE\u00C7UES</p><h3>${data.responses.length} proposition${data.responses.length > 1 ? "s" : ""} re\u00E7ue${data.responses.length > 1 ? "s" : ""}</h3></div></div>${data.responses.length > 1 ? `<section class="ec13-compare"><div class="section-heading"><div><h4>Comparer les propositions</h4><p>Tarif, délai et approche sur un même écran · sélectionnez jusqu’à 3 propositions.</p></div><button class="btn small" type="button" data-action="compare-selected">Comparer la sélection</button></div><div class="table-wrap"><table><thead><tr><th>Comparer</th><th>Prestataire</th><th>Tarif HT</th><th>Délai</th><th>Approche</th><th>Statut</th></tr></thead><tbody>${data.responses.map(r => `<tr><td><input type="checkbox" class="ec13-compare-pick" value="${e(r.id)}" aria-label="Comparer ${e(r.provider)}"></td><td><strong>${e(r.provider)}</strong></td><td>${r.price === null ? "À définir" : money(r.price)}</td><td>${r.lead_days === null ? "À préciser" : r.lead_days + " jours"}</td><td>${e((r.approach || r.message).slice(0, 100))}</td><td>${e(label(r.status))}</td></tr>`).join("")}</tbody></table></div></section>` : ""}${data.responses.length ? data.responses.map(r => `<article class="response-row"><div class="identity-row">${avatar(r.provider, null, true)}<div><h4>${e(r.provider)}</h4><small>${e(r.author)}</small></div></div><div><strong>${r.price === null ? "Tarif a convenir" : money(r.price)}</strong><small>${r.lead_days !== null ? r.lead_days + " jours" : "D\u00E9lai \u00E0 pr\u00E9ciser"}</small></div>${badge(r.status)}<p class="ec12-response-preview">${e(r.message.slice(0, 180))}${r.message.length > 180 ? "…" : ""}</p>${button("Lire la proposition complète", "view-response", { id: r.id, class: "small primary", icon: "arrow" })}</article>`).join("") : empty("Aucune proposition pour le moment", "Un brief contextualis\u00E9 et des tags pr\u00E9cis aident les bons prestataires \u00E0 vous trouver.", "", "portfolio")}</section>${data.history.length ? `<details class="history-detail"><summary>${icon("clock", 16)} Historique du besoin (${data.history.length})</summary>${data.history.slice(0, 30).map(h => `<div class="history-row"><span>${e(label(h.action))}</span><time>${dateText(h.date, true)}</time></div>`).join("")}</details>` : ""}` : ""}`;
}
export function responseDetail(r, company = null, contact = null, offers = []) {
    const card = `<div class="ec12-proposal-identity">${avatar(r.provider, company?.media || null, true)}<div><span class="eyebrow">L’ENTREPRISE QUI VOUS RÉPOND</span><h2>${e(r.provider)}</h2>${company ? labelChips({ type: company.type || 'prestataire', premium: company.premium || false, labels: company.labels }) : badge('prestataire')}<p>${e(r.author)} · ${e(r.need_title)}</p></div></div>`;
    const proposal = `<section class="ec12-proposal-section"><h3>${icon('needs', 19)} Proposition commerciale</h3><div class="prose">${markdown(r.message)}</div></section>${r.approach ? `<section class="ec12-proposal-section"><h3>${icon('target', 19)} Méthodologie, livrables et références</h3><div class="prose">${markdown(r.approach)}</div></section>` : ''}`;
    const co = company ? `<div class="ec12-proposal-company">${avatar(company.name, company.media, true)}<div><strong>${e(company.name)}</strong><small>${e(company.details?.sector || company.details?.city || 'Prestataire du réseau')}</small><p>${e((company.details?.description || '').slice(0, 220))}</p></div>${button('Voir la fiche entreprise', 'company-detail', { id: r.company_id, class: 'small ghost', icon: 'company' })}</div>` : '<p class="muted">La fiche entreprise sera accessible lorsqu’elle sera publiée.</p>';
    const person = contact ? `<div class="ec12-proposal-company">${avatar(contact.name, contact.media)}<div><strong>${e(contact.name)}</strong><small>${e(contact.subtitle || label(contact.type))}</small><p>${e((contact.description || '').slice(0, 170))}</p></div>${button('Voir la fiche contact', 'person-detail', { id: contact.id, class: 'small ghost', icon: 'user' })}</div>` : `<p>${icon('user', 16)} ${e(r.author)} — auteur de la proposition.</p>`;
    const service = offers.length ? offers.map(o => `<details class="ec12-proposal-offer"><summary><span><strong>${e(o.title)}</strong><small>${e(label(o.format))} · ${o.price === null ? 'Sur devis' : money(o.price)}</small></span>${icon('down', 17)}</summary><div class="prose">${markdown(o.description)}</div>${tags(o.tags)}${o.benefit ? `<div class="ec12-service-benefit">Avantage incubés : ${e(o.benefit)}</div>` : ''}</details>`).join('') : '<p class="muted">Aucun service publié par ce prestataire dans le catalogue.</p>';
    return `<div class="ec12-proposal-layout"><div>${card}<div class="detail-facts ec12-proposal-facts"><div><span>Tarif proposé HT</span><strong>${r.price === null ? 'À convenir' : money(r.price)}</strong></div><div><span>Délai annoncé</span><strong>${r.lead_days !== null ? r.lead_days + ' jours' : 'À préciser'}</strong></div><div><span>Statut actuel</span><strong>${e(label(r.status))}</strong></div></div>${proposal}${r.reason ? `<section class="ec12-proposal-section"><h3>Décision enregistrée</h3><div class="prose">${markdown(r.reason)}</div></section>` : ''}</div><aside class="ec12-proposal-sidebar"><div class="ec12-proposal-section"><h3>${icon('company', 18)} La société</h3>${co}</div><div class="ec12-proposal-section"><h3>${icon('user', 18)} Le répondant</h3>${person}</div><div class="ec12-proposal-section"><h3>${icon('portfolio', 18)} Ses offres publiées</h3><p class="muted small-text">Services du catalogue, distincts de la proposition personnalisée reçue.</p>${service}</div></aside></div>
    ${r.can_decide ? `<div class="decision-explainer">${icon('info', 18)}<p>Vous pouvez poursuivre la discussion sans engagement, retenir ce prestataire ou refuser sa proposition. Le prestataire voit votre décision dans son dossier.</p></div>` : ''}
    <footer class="form-footer decision-actions">${r.can_decide ? (r.status !== 'en_discussion' && r.status !== 'retenue' ? button('Engager la discussion', 'response-decision', { id: r.id, class: 'primary', icon: 'messages', extra: 'data-status="en_discussion"' }) : '') + (r.status !== 'retenue' ? button('Retenir le prestataire', 'response-decision', { id: r.id, icon: 'check', extra: 'data-status="retenue"' }) : '') + (r.status !== 'declinee' ? button('Ne pas donner suite', 'response-decision', { id: r.id, class: 'ghost danger', extra: 'data-status="declinee"' }) : '') : ''}${r.can_message ? button('Accéder à la conversation', 'open-thread', { id: r.id, icon: 'messages' }) : ''}</footer>`;
}
export function responseForm(n) { return `<form id="command-form" data-command="respond" data-id="${n.id}"><div class="inline-note compact">${icon("info", 20)}<p>Votre entreprise et votre nom seront visibles de la startup. Presentez une r\u00E9ponse concr\u00E8te a : <strong>${e(n.title)}</strong>.</p></div>${tags(n.tags)}<div class="form-grid"><div class="form-section-title span-2"><span>01</span><div><strong>Votre r\u00E9ponse</strong><small>Montrez votre compr\u00E9hension du besoin et votre valeur ajout\u00E9e.</small></div></div>${richField("message", "Votre compr\u00E9hension et votre proposition")}${field("approach", "Approche, livrables et r\u00E9f\u00E9rences utiles", "", { type: "textarea", wide: true, rows: 4 })}<div class="form-section-title span-2"><span>02</span><div><strong>Conditions indicatives</strong><small>Un tarif ou un d\u00E9lai peut rester \u00E0 convenir.</small></div></div>${field("price", "Tarif propose (EUR HT)", "", { type: "number", min: 0, help: "Laissez vide si un cadrage est n\u00E9cessaire." })}${field("lead_days", "D\u00E9lai estim\u00E9 (jours)", "", { type: "number", min: 0, max: 3650 })}</div>${footerSubmit("Envoyer ma proposition")}</form>`; }
export function statusForm(n) { return `<form id="command-form" data-command="need_status" data-id="${n.id}"><p class="muted">Le statut est visible par les membres autoris\u00E9s a consulter votre demande. Les d\u00E9cisions sur chaque proposition restent distinctes.</p>${selectField("status", "Avancement de la demande", needStatuses.filter(s => !["termine", "sans_suite"].includes(n.status) || s === "ouvert").map(v => ({ value: v, label: v === "ouvert" && isClosed(n.status) ? "Reouvrir la demande" : label(v) })), n.status)}${field("reason", "Motif ou pr\u00E9cision", "", { type: "textarea", help: "Requis pour une mise en pause ou une cloture sans suite." })}${footerSubmit("Mettre \u00E0 jour")}</form>`; }
export function sessionForm(ctx, kind = "creneau", responseId = null) {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    const start = localDate(tomorrow) + "T09:00";
    return `<form id="command-form" data-command="create_session"><input type="hidden" name="response_id" value="${responseId || ""}"><input type="hidden" name="company" value="${ctx.companyId || ""}"><div class="inline-note compact">${icon("calendar", 20)}<p>Les horaires sont saisis en <strong>Europe/Paris</strong>. Les conflits sont contr\u00F4les c\u00F4t\u00E9 serveur. Une permanence cr\u00E9\u00E9 des cr\u00E9neaux individuels successifs.</p></div><div class="form-grid">${kind === "proposition" ? "<input type=\"hidden\" name=\"kind\" value=\"proposition\">" : selectField("kind", "Format de rencontre", ["creneau", "permanence", "atelier"].map(v => ({ value: v, label: label(v) })), kind, true)}${field("title", "Objet de la rencontre", kind === "permanence" ? "Permanence d'expertise" : kind === "proposition" ? "\u00C9change de cadrage sur votre besoin" : "", { required: true, wide: true, placeholder: "Ex. Cadrer sa strat\u00E9gie de financement" })}${field("description", "Objectifs et deroulement", "", { type: "textarea", wide: true, placeholder: "Ce que les participants pourront aborder ou apprendre." })}${field("start_local", "Date et heure de debut", start, { type: "datetime-local", required: true })}${selectField("duration", "Dur\u00E9e de chaque rendez-vous", [15, 30, 45, 60, 90, 120, 180, 240].map(v => ({ value: String(v), label: v + " minutes" })), "30")}
 ${selectField("mode", "Modalit\u00E9", ["visio", "telephone", "sur_site"].map(v => ({ value: v, label: label(v) })), "visio")}${field("location", "Adresse, t\u00E9l\u00E9phone ou lien de visioconf\u00E9rence", "", { placeholder: "Lien accessible aux personnes inscrites" })}
 <div class="permanence-fields span-2 form-grid" ${kind !== "permanence" ? "hidden" : ""}>${selectField("block_minutes", "Amplitude de la permanence", [60, 90, 120, 180, 240, 480].map(v => ({ value: String(v), label: v + " minutes" })), "120")}${selectField("break_minutes", "Pause entre deux rendez-vous", [0, 5, 10, 15, 30].map(v => ({ value: String(v), label: v + " minutes" })), "0")}${selectField("weeks", "R\u00E9p\u00E9tition chaque semaine", [1, 2, 4, 8, 12].map(v => ({ value: String(v), label: v === 1 ? "Cette date uniquement" : v + " semaines" })), "1")}</div>
 <div class="workshop-fields span-2" ${kind !== "atelier" ? "hidden" : ""}>${field("capacity", "Nombre de participants maximum", "20", { type: "number", min: 1, max: 200 })}</div><div class="span-2">${tagField()}</div></div>${footerSubmit(kind === "proposition" ? "Envoyer la proposition de rendez-vous" : kind === "atelier" ? "Publier l'atelier" : "Publier les disponibilit\u00E9s")}</form>`;
}
export function sessionDetail(ctx, s) {
    const registered = ["confirme", "present", "absent"].includes(s.registration || "");
    const future = new Date(s.starts_at) > new Date();
    const safeLink = /^https:\/\//i.test(s.location) ? s.location : null;
    return `<div class="detail-badges">${badge(s.kind)}${badge(s.registration || s.status)}</div><h2 class="detail-title">${e(s.title)}</h2><div class="identity-row">${avatar(s.host_name, null)}<div><strong>${e(s.host_name)}</strong><small>${e(s.company_name || "\u00C9quipe d'accompagnement")}</small></div></div><div class="detail-facts"><div><span>Date</span><strong>${dateText(s.starts_at)}</strong></div><div><span>Horaire</span><strong>${timeText(s.starts_at)} - ${timeText(s.ends_at)}</strong></div><div><span>Modalit\u00E9</span><strong>${e(label(s.mode))}</strong></div><div><span>Places</span><strong>${s.occupied} / ${s.capacity}</strong></div></div><div class="prose">${markdown(s.description || "Un temps d'\u00E9change pour faire avancer votre projet.")}</div>${s.location ? `<div class="location-box">${icon(s.mode === "visio" ? "video" : "location", 21)}${safeLink ? `<a href="${e(safeLink)}" target="_blank" rel="noopener noreferrer">Rejoindre la visioconf\u00E9rence ${icon("arrow", 15)}</a>` : `<span>${e(s.location)}</span>`}</div>` : ""}${s.purpose ? "<div class=\"prose\"><h4>Votre objectif</h4>" + markdown(s.purpose) + "</div>" : ""}
 ${!registered && !s.can_manage && s.registration !== "attente" && s.status === "ouvert" && future ? `<form id="command-form" data-command="book_session" data-id="${s.id}"><input type="hidden" name="company" value="${ctx.companyId || ""}">${field("purpose", s.kind === "atelier" ? "Vos attentes pour cet atelier" : "Pourquoi souhaitez-vous ce rendez-vous ?", "", { type: "textarea", required: s.kind !== "atelier", placeholder: "D\u00E9crivez les sujets a aborder. Ne renseignez pas de coordonn\u00E9es ici." })}<div class="form-error" role="alert" hidden></div><footer class="form-footer"><button type="submit" class="btn primary">${icon("calendar", 18)}${s.occupied >= s.capacity ? "Rejoindre la liste d'attente" : "Confirmer mon inscription"}</button></footer></form>` : ""}
 <footer class="form-footer">${registered || s.can_manage ? button("Ajouter a mon calendrier", "export-ics", { id: s.id, icon: "download" }) : ""}${s.registration && ["confirme", "attente"].includes(s.registration) && future ? button("Annuler mon inscription", "cancel-booking", { id: s.id, class: "ghost danger" }) : ""}${s.can_reply && s.status === "ouvert" && future ? button("Refuser ce créneau", "decline-session", { id: s.id, class: "ghost danger" }) + (s.response_id ? button("Proposer un autre créneau", "propose", { id: s.response_id, class: "ghost", icon: "calendar" }) : "") : ""}${s.can_manage && s.status === "ouvert" ? button("Annuler la rencontre", "cancel-session", { id: s.id, class: "ghost danger" }) : ""}${s.can_manage && s.status === "ouvert" && new Date(s.ends_at) <= new Date() ? button("Marquer comme r\u00E9alis\u00E9", "complete-session", { id: s.id, class: "primary", icon: "check" }) : ""}</footer>
 ${s.can_manage && s.participants.length ? `<section class="mt"><div class="section-heading"><h3>Participants</h3><span class="muted">Identit\u00E9s soumises aux m\u00EAmes droits Premium.</span></div>${s.participants.map(p => `<div class="contact-row"><div><strong>${e(p.name)}</strong><small>${e(p.company || "Membre du r\u00E9seau")}</small><p>${e(p.purpose)}</p></div>${badge(p.status)}${!future && ["confirme", "present", "absent"].includes(p.status) ? `<div class="table-actions">${button("Present", "attendance", { id: p.id, class: "small", extra: "data-status=\"present\"" })}${button("Absent", "attendance", { id: p.id, class: "small ghost", extra: "data-status=\"absent\"" })}</div>` : ""}</div>`).join("")}</section>` : ""}`;
}
export function companyPage(ctx, company) {
    const p = ctx.boot.profile;
    return `<div class="page-head"><div><p class="eyebrow">VOTRE PR\u00C9SENCE DANS LE R\u00C9SEAU</p><h1>Entreprise & profil</h1><p>Une entreprise partag\u00E9e. Des contacts et des expertises identifiables.</p></div></div><div class="profile-layout"><section class="panel"><div class="section-heading"><h2>Ma fiche contact</h2>${button("Modifier", "edit-profile", { class: "small", icon: "edit" })}</div><div class="profile-hero">${avatar(ctx.boot.user.name || ctx.boot.user.email, p.media)}<div><h3>${e(ctx.boot.user.name || "Profil a compl\u00E9ter")}</h3><p>${e(p.titre || roleLabels[ctx.boot.user.role])}</p>${badge(ctx.boot.user.role)}${p.linkedin_url ? `<a class="ec12-linkedin-link" href="${e(p.linkedin_url)}" target="_blank" rel="noopener noreferrer">Mon profil LinkedIn ↗</a>` : ""}</div></div><p>${e(p.bio_html || "Presentez votre r\u00F4le et les comp\u00E9tences que vous souhaitez partager.")}</p>${tags(p.tags || [])}<div class="profile-actions">${button(p.media ? "Changer ma photo" : "Ajouter ma photo", "upload", { id: ctx.boot.user.id, icon: "upload", class: "primary", extra: "data-type=\"person\"" })}</div><p class="muted small-text">Photo redimensionnée avant envoi. Pour une photo LinkedIn, téléchargez votre propre image depuis votre profil LinkedIn, puis utilisez « Ajouter ma photo ». Aucun accès automatique au compte LinkedIn.</p></section><section class="panel"><div class="section-heading"><h2>Mon entreprise</h2>${company?.can_edit ? button("Modifier", "edit-company", { id: company.id, class: "small", icon: "edit" }) : ""}</div>${company ? `<div class="profile-hero">${avatar(company.name, company.media, true)}<h3>${e(company.name)}</h3></div>${badge(ctx.company?.type || "autre")}<p>${e(company.details?.description || "Pr\u00E9sentation de l'entreprise a compl\u00E9ter.")}</p>${tags(company.tags)}<div class="profile-actions">${company.can_edit ? button("Ajouter un logo", "upload", { id: company.id, icon: "upload", extra: "data-type=\"company\"" }) + button("G\u00E9rer les membres", "manage-members", { id: company.id, icon: "people" }) : ""}</div><div class="contact-row"><span>${company.members.length} contact${company.members.length > 1 ? "s" : ""} rattach\u00E9${company.members.length > 1 ? "s" : ""}</span>${ctx.company?.premium ? "<span class=\"premium-label\">Premium actif</span>" : ""}</div>` : empty("Votre entreprise n est pas encore configur\u00E9e", "Creez sa fiche ou demandez un rattachement \u00E0 son propri\u00E9taire.", ["incube", "prestataire", "admin"].includes(ctx.boot.user.role) ? button("Cr\u00E9er mon entreprise", "new-company", { class: "primary", icon: "company" }) : "", "company")}</section></div><section class="panel mt"><div class="section-heading"><h2>S\u00E9curit\u00E9 du compte</h2></div><p class="muted">Le r\u00F4le et les droits Premium sont g\u00E9r\u00E9s exclusivement par l'administrateur.</p>${button("Modifier mon mot de passe", "change-password", { icon: "lock" })}</section>`;
}
export function profileForm(ctx) { return `<form id="command-form" data-command="save_profile"><div class="form-grid">${field("name", "Pr\u00E9nom et nom", ctx.boot.user.name || "", { required: true })}${field("title", "Fonction ou accroche", ctx.boot.profile.titre || "")}${field("linkedin_url", "URL de votre profil LinkedIn", ctx.boot.profile.linkedin_url || "", { type: "url", wide: true, placeholder: "https://www.linkedin.com/in/votre-profil", help: "Lien public uniquement. LinkedIn ne permet pas ici un import automatique fiable des données et photos ; vous pouvez ajouter votre photo séparément." })}${field("bio", "Pr\u00E9sentation", ctx.boot.profile.bio_html || "", { type: "textarea", wide: true })}${tagField(ctx.boot.profile.tags || [])}<div class="span-2">${checkField("visible", "Afficher mon profil dans l'annuaire, selon les r\u00E8gles de confidentialit\u00E9.", ctx.boot.profile.visible !== false)}</div></div>${footerSubmit("Enregistrer mon profil")}</form>`; }
export function companyForm(ctx, data, admin) { return `<form id="command-form" data-command="save_company" data-id="${data?.id || ""}"><div class="form-grid">${field("name", "Nom de l'entreprise", data?.name || "", { required: true, wide: true })}${!data && ctx.boot.user.role === "admin" ? selectField("type", "Typologie", ["startup", "prestataire", "autre"].map(v => ({ value: v, label: label(v) })), "autre") + selectField("owner_id", "Propri\u00E9taire (compte existant)", [{ value: "", label: "S\u00E9lectionnez pour une entreprise prestataire" }, ...(admin?.users || []).filter(u => u.role === "incube" || u.role === "prestataire").map(u => ({ value: u.id, label: (u.name || u.email) + " - " + roleLabels[u.role] }))]) : ""}${richField("description", "Pr\u00E9sentation de l'entreprise", data?.details?.description || "")}${field("sector", "Secteur d'activit\u00E9", data?.details?.sector || "")}${field("city", "Ville / territoire", data?.details?.city || "")}${tagField(data?.tags || [])}${field("email", "Contact professionnel", data?.details?.contact_email || "", { type: "email" })}${field("phone", "T\u00E9l\u00E9phone", data?.details?.phone || "", { type: "tel" })}<div class="span-2">${checkField("share_contact", "Partager ces coordonn\u00E9es avec les membres autoris\u00E9s a voir mon identit\u00E9.", data?.details?.share_contact || false)}</div></div>${footerSubmit(data ? "Enregistrer l'entreprise" : "Cr\u00E9er l'entreprise")}</form>`; }
export function offerForm(offer) { return `<form id="command-form" data-command="save_offer" data-id="${offer?.id || ""}"><div class="form-grid">${field("title", "Intitul\u00E9 du service", offer?.title || "", { required: true, wide: true })}${richField("description", "P\u00E9rim\u00E8tre et livrables", offer?.description || "")}${tagField(offer?.tags || [])}${selectField("format", "Modalit\u00E9", formatOptions, offer?.format || "distance")}${field("price", "Tarif indicatif (EUR HT)", fromCents(offer?.price), { type: "number", min: 0, help: "Vide = sur devis." })}${field("benefit", "Avantage r\u00E9serv\u00E9 aux incub\u00E9s", offer?.benefit || "", { type: "textarea", wide: true, help: "Visible des incub\u00E9s et de l'\u00E9quipe d'accompagnement." })}</div>${footerSubmit("Enregistrer l'offre")}</form>`; }
